  <style>
    :root {
      --primary-color: #2563eb;
      --primary-hover: #1d4ed8;
      --bg-color: #f8fafc;
      --card-bg: #ffffff;
      --text-main: #0f172a;
      --text-muted: #475569;
      --radio-border: #64748b;
      --error-color: #dc2626;
      --success-text: #15803d;
      --success-bg: #f0fdf4;
      --success-border: #bbf7d0;
      --focus-ring: #93c5fd;
    }

    body {
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background-color: var(--bg-color);
      color: var(--text-main);
      line-height: 1.5;
      margin: 0;
      padding: 2rem;
      display: flex;
      justify-content: center;
    }

    .container {
      background-color: var(--card-bg);
      padding: 2rem;
      border-radius: 8px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
      width: 100%;
      max-width: 480px;
    }

    h1 {
      font-size: 1.5rem;
      margin-top: 0;
      margin-bottom: 1.5rem;
      font-weight: 600;
    }

    fieldset {
      border: none;
      padding: 0;
      margin: 0;
    }

    legend {
      font-weight: 600;
      font-size: 1.125rem;
      margin-bottom: 0.5rem;
      padding: 0;
    }

    .help-text {
      font-size: 0.875rem;
      color: var(--text-muted);
      margin-top: 0;
      margin-bottom: 1.25rem;
    }

    .form-field {
      margin-bottom: 2rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      margin-bottom: 0.75rem;
    }

    .radio-option input[type="radio"] {
      appearance: none;
      background-color: #fff;
      margin: 0;
      font: inherit;
      color: currentColor;
      width: 1.25em;
      height: 1.25em;
      border: 2px solid var(--radio-border);
      border-radius: 50%;
      display: grid;
      place-content: center;
      cursor: pointer;
    }

    .radio-option input[type="radio"]::before {
      content: "";
      width: 0.65em;
      height: 0.65em;
      border-radius: 50%;
      transform: scale(0);
      transition: 120ms transform ease-in-out;
      box-shadow: inset 1em 1em var(--primary-color);
    }

    .radio-option input[type="radio"]:checked::before {
      transform: scale(1);
    }

    .radio-option input[type="radio"]:checked {
      border-color: var(--primary-color);
    }

    .radio-option input[type="radio"]:focus-visible {
      outline: 3px solid var(--focus-ring);
      outline-offset: 2px;
    }

    .radio-option label {
      margin-left: 0.5rem;
      cursor: pointer;
      font-size: 1rem;
    }

    .submit-btn {
      background-color: var(--primary-color);
      color: white;
      border: none;
      padding: 0.75rem 1.5rem;
      font-size: 1rem;
      font-weight: 500;
      border-radius: 6px;
      cursor: pointer;
      width: 100%;
      transition: background-color 0.2s;
    }

    .submit-btn:hover {
      background-color: var(--primary-hover);
    }

    .submit-btn:focus-visible {
      outline: 3px solid var(--focus-ring);
      outline-offset: 2px;
    }

    .error-message {
      color: var(--error-color);
      font-size: 0.875rem;
      margin-top: 1rem;
      margin-bottom: 0;
      display: flex;
      align-items: center;
    }

    .error-message[hidden] {
      display: none;
    }

    .status-message {
      margin-top: 1.5rem;
      padding: 1rem;
      background-color: var(--success-bg);
      color: var(--success-text);
      border: 1px solid var(--success-border);
      border-radius: 6px;
      font-weight: 500;
      text-align: center;
    }

    .status-message[hidden] {
      display: none;
    }
  </style>
</head>
<body>
  <main class="container">
    <h1>Notification Settings</h1>

    <form id="notification-form" novalidate>
      <div class="form-field">
        <fieldset aria-describedby="notification-help">
          <legend>How do you prefer to receive notifications? <span aria-hidden="true">*</span></legend>
          <p id="notification-help" class="help-text">Select one option to stay updated. Required fields are marked with an asterisk (*).</p>

          <div class="radio-option">
            <input type="radio" id="pref-email" name="notification_preference" value="Email" required>
            <label for="pref-email">Email</label>
          </div>

          <div class="radio-option">
            <input type="radio" id="pref-sms" name="notification_preference" value="SMS" required>
            <label for="pref-sms">SMS</label>
          </div>

          <div class="radio-option">
            <input type="radio" id="pref-push" name="notification_preference" value="Push Notifications" required>
            <label for="pref-push">Push Notifications</label>
          </div>

          <p id="notification-error" class="error-message" hidden>Error: Please select a notification preference.</p>
        </fieldset>
      </div>

      <button type="submit" class="submit-btn">Save Preference</button>
    </form>

    <div id="status-message" role="status" aria-live="polite" class="status-message" hidden></div>
  </main>

  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const form = document.getElementById('notification-form');
      const errorMsg = document.getElementById('notification-error');
      const statusMsg = document.getElementById('status-message');
      const fieldset = form.querySelector('fieldset');
      const radios = form.querySelectorAll('input[name="notification_preference"]');

      form.addEventListener('submit', (e) => {
        e.preventDefault();

        let isChecked = false;
        let firstRadio = radios[0];

        // Check if any radio is selected
        radios.forEach(radio => {
          if (radio.checked) {
            isChecked = true;
          }
        });

        if (!isChecked) {
          // Show error and move focus to first invalid control
          errorMsg.hidden = false;
          radios.forEach(r => r.setAttribute('aria-invalid', 'true'));
          fieldset.setAttribute('aria-describedby', 'notification-help notification-error');
          statusMsg.hidden = true;
          firstRadio.focus();
        } else {
          // Valid submission
          errorMsg.hidden = true;
          radios.forEach(r => r.removeAttribute('aria-invalid'));
          fieldset.setAttribute('aria-describedby', 'notification-help');

          const selectedValue = form.querySelector('input[name="notification_preference"]:checked').value;
          statusMsg.textContent = `Preference saved: ${selectedValue}`;
          statusMsg.hidden = false;
        }
      });

      // Clear error as soon as user makes a selection
      radios.forEach(radio => {
        radio.addEventListener('change', () => {
          errorMsg.hidden = true;
          radios.forEach(r => r.removeAttribute('aria-invalid'));
          fieldset.setAttribute('aria-describedby', 'notification-help');
        });
      });
    });
  </script>
</body>
